'use client';

import { useState } from 'react';
import { BuilderToolbar } from '@/features/document-engine/components/builder-toolbar';
import { EditorPane } from '@/features/document-engine/components/editor-pane';
import { PreviewPane } from '@/features/document-engine/components/preview-pane';

export default function DocumentBuilderPage() {
  const [content, setContent] = useState(`Yth. {{nama_pegawai}}
NIP: {{nip_pegawai}}

Dengan hormat,
Sehubungan dengan kegiatan rapat tahunan, kami mengharap kehadiran Bapak/Ibu pada:

Hari/Tanggal: {{tanggal_rapat}}
Waktu: {{waktu_rapat}}
Tempat: {{lokasi_rapat}}

Demikian undangan ini kami sampaikan, atas perhatian dan kehadirannya diucapkan terima kasih.

Mengetahui,
Kepala Sekolah

{{ttd_kepala_sekolah}}
`);

  const [previewMode, setPreviewMode] = useState(false);
  const [validationResult, setValidationResult] = useState<any>(null);

  // Fungsi Test Render sederhana di Client-side
  const handleTestRender = () => {
    // Simulasi dummy data
    const dummy = {
      nama_pegawai: 'Budi Santoso, S.Pd',
      nip_pegawai: '198012122005011001',
      tanggal_rapat: 'Senin, 20 Agustus 2026',
      waktu_rapat: '09:00 WIB',
      lokasi_rapat: 'Ruang Rapat Utama',
      ttd_kepala_sekolah: '[TTD_QR_CODE]'
    };

    let rendered = content;
    const regex = /\{\{([a-zA-Z0-9_]+)\}\}/g;

    // Validasi missing
    const extracted = [...content.matchAll(regex)].map(m => m[1]);
    const missing = extracted.filter(k => !(k in dummy));

    rendered = rendered.replace(regex, (match, key) => {
      return (dummy as any)[key] || `<span class="bg-red-100 text-red-600 font-bold px-1 rounded">[KOSONG: ${key}]</span>`;
    });

    setValidationResult({
      html: rendered.replace(/\n/g, '<br/>'),
      missing
    });
    setPreviewMode(true);
  };

  return (
    <div className="h-[calc(100vh-5rem)] flex flex-col -m-6 bg-gray-50">
      <BuilderToolbar onTestRender={handleTestRender} />

      {/* Editor & Preview Pane */}
      <div className="flex-1 flex overflow-hidden">
        <EditorPane 
          content={content} 
          onChange={setContent} 
          previewMode={previewMode} 
        />
        <PreviewPane 
          previewMode={previewMode} 
          onClosePreview={() => setPreviewMode(false)} 
          validationResult={validationResult} 
        />
      </div>
    </div>
  );
}

import { Metadata } from 'next';
import { db } from '@/db';
import { outgoingLetters } from '@/db/schema/outgoing-letter';
import { desc, eq, isNull } from 'drizzle-orm';
import { Button } from '@/components/ui/button';
import { Plus } from 'lucide-react';
import Link from 'next/link';

export const metadata: Metadata = {
  title: 'Surat Keluar | PAWARTA',
};

export default async function SuratKeluarPage() {
  const letters = await db
    .select()
    .from(outgoingLetters)
    .where(isNull(outgoingLetters.deletedAt))
    .orderBy(desc(outgoingLetters.createdAt));

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">Surat Keluar</h2>
        <div className="flex items-center space-x-2">
          <Link href="/surat-keluar/create">
            <Button>
              <Plus className="mr-2 h-4 w-4" />
              Buat Surat
            </Button>
          </Link>
        </div>
      </div>

      <div className="rounded-md border p-4 bg-white shadow-sm">
        {/* Placeholder for complex DataTable */}
        <p className="text-sm text-muted-foreground mb-4">Menampilkan {letters.length} data surat keluar.</p>

        {letters.length === 0 ? (
          <div className="text-center py-10">Belum ada surat keluar. Silakan buat draft baru.</div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="bg-muted">
              <tr>
                <th className="p-3">Perihal</th>
                <th className="p-3">Tujuan</th>
                <th className="p-3">Status</th>
                <th className="p-3">Tanggal</th>
                <th className="p-3">Aksi</th>
              </tr>
            </thead>
            <tbody>
              {letters.map((l) => (
                <tr key={l.id} className="border-b">
                  <td className="p-3 font-medium">{l.perihal}</td>
                  <td className="p-3">{l.tujuanSurat}</td>
                  <td className="p-3">
                    <span className="bg-primary/10 text-primary px-2 py-1 rounded-full text-xs">
                      {l.status}
                    </span>
                  </td>
                  <td className="p-3">{l.createdAt?.toLocaleDateString()}</td>
                  <td className="p-3">
                    <Link href={`/surat-keluar/${l.id}`}>
                      <Button variant="outline" size="sm">Detail</Button>
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { db } from '@/db';
import { incomingLetters } from '@/db/schema/incoming-letter';
import { authenticateApiRequest } from '@/lib/api-auth';
import { desc } from 'drizzle-orm';

export async function GET(req: Request) {
  const auth = await authenticateApiRequest(req, '/api/v1/letters/incoming');
  if (auth.error) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  try {
    const letters = await db
      .select({
        id: incomingLetters.id,
        nomorSurat: incomingLetters.nomorSurat,
        perihal: incomingLetters.perihal,
        pengirim: incomingLetters.pengirim,
        tanggalSurat: incomingLetters.tanggalSurat,
        status: incomingLetters.status,
      })
      .from(incomingLetters)
      .orderBy(desc(incomingLetters.createdAt))
      .limit(50); // Default limit for API

    return NextResponse.json({
      success: true,
      count: letters.length,
      data: letters,
    });
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

export async function POST(req: Request) {
  const auth = await authenticateApiRequest(req, '/api/v1/letters/incoming');
  if (auth.error) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  // Cek Permission (simulasi)
  const permissions = (auth.apiKey?.permissions as string[]) || [];
  if (!permissions.includes('write:letters')) {
    return NextResponse.json({ error: 'Forbidden: Missing write:letters permission' }, { status: 403 });
  }

  try {
    const body = await req.json();

    // Validasi basic manual untuk API (idealnya pakai Zod sama seperti Server Action)
    if (!body.perihal || !body.pengirim) {
      return NextResponse.json({ error: 'Field perihal and pengirim are required' }, { status: 400 });
    }

    const [newLetter] = await db.insert(incomingLetters).values({
      perihal: body.perihal,
      pengirim: body.pengirim,
      nomorSurat: body.nomorSurat || 'TBA',
      tanggalSurat: new Date(body.tanggalSurat || Date.now()),
      tanggalDiterima: new Date(),
      status: 'DRAFT',
      prioritasId: body.prioritasId || null,
      jenisSuratId: body.jenisSuratId || null,
    }).returning();

    return NextResponse.json({
      success: true,
      message: 'Surat Masuk berhasil diregistrasi via API',
      data: newLetter,
    }, { status: 201 });

  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@/db';
import { incomingLetters } from '@/db/schema/incoming-letter';
import { outgoingLetters } from '@/db/schema/outgoing-letter';
import { archives } from '@/db/schema/archive';
import { authenticateApiRequest } from '@/lib/api-auth';
import { sql } from 'drizzle-orm';

export async function GET(req: Request) {
  const auth = await authenticateApiRequest(req, '/api/v1/reports/summary');
  if (auth.error) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  try {
    // 1. Total Incoming Letters
    const [incomingCount] = await db
      .select({ count: sql<number>`count(*)` })
      .from(incomingLetters);

    // 2. Total Outgoing Letters
    const [outgoingCount] = await db
      .select({ count: sql<number>`count(*)` })
      .from(outgoingLetters);

    // 3. Total Archives
    const [archiveCount] = await db
      .select({ count: sql<number>`count(*)` })
      .from(archives);

    return NextResponse.json({
      success: true,
      data: {
        suratMasuk: incomingCount?.count || 0,
        suratKeluar: outgoingCount?.count || 0,
        arsipDigital: archiveCount?.count || 0,
        timestamp: new Date().toISOString(),
      },
    });
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useRouter } from 'next/navigation';
import { incomingLetterSchema, IncomingLetterFormValues } from '@/features/incoming-letter/validations';
import { registerIncomingLetter } from '@/features/incoming-letter/actions';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

export function IncomingLetterForm({ 
  jenisSuratOpts = [], 
  klasifikasiOpts = [], 
  prioritasOpts = [], 
  sifatOpts = [],
  instansiOpts = []
}: any) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { register, handleSubmit, formState: { errors } } = useForm<IncomingLetterFormValues>({
    resolver: zodResolver(incomingLetterSchema),
    defaultValues: {
      tanggalSurat: new Date().toISOString().split('T')[0],
      tanggalDiterima: new Date().toISOString().split('T')[0],
    }
  });

  const onSubmit = async (data: IncomingLetterFormValues) => {
    setLoading(true);
    setError(null);
    const result = await registerIncomingLetter(data);
    setLoading(false);

    if (result.error) {
      setError(result.error);
    } else {
      router.push('/surat-masuk');
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
      {error && <div className="p-3 bg-red-100 text-red-600 rounded">{error}</div>}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="nomorSurat">Nomor Surat</Label>
          <Input id="nomorSurat" {...register('nomorSurat')} />
          {errors.nomorSurat && <span className="text-sm text-red-500">{errors.nomorSurat.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="pengirim">Pengirim (Nama)</Label>
          <Input id="pengirim" {...register('pengirim')} />
          {errors.pengirim && <span className="text-sm text-red-500">{errors.pengirim.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="instansiPengirimId">Instansi Pengirim (Opsional)</Label>
          <select 
            id="instansiPengirimId" 
            {...register('instansiPengirimId')} 
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            <option value="">-- Pilih Instansi --</option>
            {instansiOpts.map((opt: any) => (
              <option key={opt.id} value={opt.id}>{opt.nama}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="tanggalSurat">Tanggal Surat</Label>
          <Input id="tanggalSurat" type="date" {...register('tanggalSurat')} />
          {errors.tanggalSurat && <span className="text-sm text-red-500">{errors.tanggalSurat.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="tanggalDiterima">Tanggal Diterima</Label>
          <Input id="tanggalDiterima" type="date" {...register('tanggalDiterima')} />
          {errors.tanggalDiterima && <span className="text-sm text-red-500">{errors.tanggalDiterima.message}</span>}
        </div>

        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="perihal">Perihal</Label>
          <Input id="perihal" {...register('perihal')} />
          {errors.perihal && <span className="text-sm text-red-500">{errors.perihal.message}</span>}
        </div>

        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="ringkasanIsi">Ringkasan Isi</Label>
          <textarea 
            id="ringkasanIsi" 
            {...register('ringkasanIsi')}
            className="flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="jenisSuratId">Jenis Surat</Label>
          <select 
            id="jenisSuratId" 
            {...register('jenisSuratId')} 
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
          >
            <option value="">-- Pilih Jenis --</option>
            {jenisSuratOpts.map((opt: any) => (
              <option key={opt.id} value={opt.id}>{opt.nama}</option>
            ))}
          </select>
          {errors.jenisSuratId && <span className="text-sm text-red-500">{errors.jenisSuratId.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="klasifikasiId">Klasifikasi</Label>
          <select 
            id="klasifikasiId" 
            {...register('klasifikasiId')} 
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
          >
            <option value="">-- Pilih Klasifikasi --</option>
            {klasifikasiOpts.map((opt: any) => (
              <option key={opt.id} value={opt.id}>{opt.kode} - {opt.nama}</option>
            ))}
          </select>
          {errors.klasifikasiId && <span className="text-sm text-red-500">{errors.klasifikasiId.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="prioritasId">Prioritas</Label>
          <select 
            id="prioritasId" 
            {...register('prioritasId')} 
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
          >
            <option value="">-- Pilih Prioritas --</option>
            {prioritasOpts.map((opt: any) => (
              <option key={opt.id} value={opt.id}>{opt.nama}</option>
            ))}
          </select>
          {errors.prioritasId && <span className="text-sm text-red-500">{errors.prioritasId.message}</span>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="sifatSuratId">Sifat Surat</Label>
          <select 
            id="sifatSuratId" 
            {...register('sifatSuratId')} 
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
          >
            <option value="">-- Pilih Sifat --</option>
            {sifatOpts.map((opt: any) => (
              <option key={opt.id} value={opt.id}>{opt.nama}</option>
            ))}
          </select>
          {errors.sifatSuratId && <span className="text-sm text-red-500">{errors.sifatSuratId.message}</span>}
        </div>

        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="catatan">Catatan</Label>
          <Input id="catatan" {...register('catatan')} />
        </div>
      </div>

      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" onClick={() => router.back()} disabled={loading}>Batal</Button>
        <Button type="submit" disabled={loading}>{loading ? 'Menyimpan...' : 'Registrasi Surat'}</Button>
      </div>
    </form>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Search, Command, FileText, Users, Settings, Building2 } from 'lucide-react';

export function CommandPaletteTrigger() {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) => !open);
      }
    };
    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, []);

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="flex items-center gap-2 text-sm text-gray-500 bg-gray-50 hover:bg-gray-100 hover:text-gray-900 px-4 py-2 rounded-lg border border-gray-200 w-full sm:w-64 transition-all focus:outline-none focus:ring-2 focus:ring-blue-500/20"
      >
        <Search className="w-4 h-4" />
        <span className="flex-1 text-left hidden sm:inline-block">Cari sesuatu...</span>
        <span className="text-left sm:hidden">Cari...</span>
        <kbd className="hidden sm:inline-flex items-center gap-1 rounded border border-gray-300 bg-white px-1.5 font-mono text-[10px] font-medium text-gray-500">
          <span className="text-xs">⌘</span>K
        </kbd>
      </button>

      {/* Basic Command Palette Mockup (sementara karena menunggu instalasi CMD-K shadcn) */}
      {open && (
        <div className="fixed inset-0 z-50 bg-gray-900/50 backdrop-blur-sm flex items-start justify-center pt-[15vh]">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col border border-gray-200 animate-in fade-in zoom-in-95">
            <div className="flex items-center px-4 border-b border-gray-100">
              <Search className="w-5 h-5 text-gray-400" />
              <input
                autoFocus
                className="flex-1 h-12 bg-transparent border-0 px-4 text-sm focus:outline-none focus:ring-0"
                placeholder="Ketik perintah atau cari..."
              />
              <button onClick={() => setOpen(false)} className="text-[10px] font-medium text-gray-400 bg-gray-100 px-2 py-1 rounded">
                ESC
              </button>
            </div>

            <div className="max-h-[60vh] overflow-y-auto p-2">
              <div className="px-2 py-1.5 text-xs font-semibold text-gray-500">Master Data</div>
              <button className="w-full flex items-center gap-3 px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-blue-600 rounded-lg transition-colors text-left">
                <Building2 className="w-4 h-4" /> Instansi & Unit Kerja
              </button>
              <button className="w-full flex items-center gap-3 px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-blue-600 rounded-lg transition-colors text-left">
                <Users className="w-4 h-4" /> Pegawai
              </button>

              <div className="px-2 py-1.5 mt-2 text-xs font-semibold text-gray-500">Surat & Template</div>
              <button className="w-full flex items-center gap-3 px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-blue-600 rounded-lg transition-colors text-left">
                <FileText className="w-4 h-4" /> Cari Template Surat
              </button>

              <div className="px-2 py-1.5 mt-2 text-xs font-semibold text-gray-500">Sistem</div>
              <button className="w-full flex items-center gap-3 px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-blue-600 rounded-lg transition-colors text-left">
                <Settings className="w-4 h-4" /> Pengaturan Preferensi
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

