});

// ==========================================
// 3. Attachments
// ==========================================
export const incomingLetterAttachments = pgTable('incoming_letter_attachments', {
  ...auditFields,
  suratId: uuid('surat_id').notNull().references(() => incomingLetters.id, { onDelete: 'cascade' }),
