import { db } from '@/db';
import { 
  archives, 
  archiveHistories, 
  archiveBorrowings, 
  documentHashes, 
  documentVerifications,
  documentFavorites,
  retentionPolicies
} from '@/db/schema/archive';
import { requireAuth, logActivity } from '@/lib/server-action';
import { 
  archiveDocumentSchema, 
  ArchiveDocumentFormValues,
  borrowArchiveSchema,
  BorrowArchiveFormValues
} from './validations';
