  try {
    const user = await requireAuth();
    const [inserted] = await db.insert(permissions).values(data).returning();

    await logActivity({
      userId: user.id!,
      action: 'CREATE',
      entityType: 'IAM_PERMISSION',
      entityId: inserted.id,
      details: { kode: data.kode }
    });

    revalidatePath('/dashboard/iam/permissions');
    return { success: true };
