'use server';

import { db } from '@/db';
import { workflowInstances, workflowSteps, workflowHistories } from '@/db/schema/workflow';
import { outgoingLetters } from '@/db/schema/outgoing-letter';
import { requireAuth, logActivity } from '@/lib/server-action';
import { eq, and } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';

// Fungsi generic untuk submit surat ke step selanjutnya
export async function submitWorkflow(instanceId: string, action: string, catatan: string = '') {
  const user = await requireAuth();

  try {
    const result = await db.transaction(async (tx) => {
      // 1. Dapatkan Instance saat ini
      const [instance] = await tx
        .select()
        .from(workflowInstances)
        .where(eq(workflowInstances.id, instanceId));

      if (!instance) throw new Error('Workflow tidak ditemukan');

      // 2. Dapatkan Step saat ini
      const [currentStep] = await tx
        .select()
        .from(workflowSteps)
        .where(eq(workflowSteps.id, instance.currentStepId));

      // 3. Tentukan Next Step berdasarkan action (Sederhana: cari step dengan urutan + 1)
      let nextStep;
      if (action === 'APPROVE' || action === 'SUBMIT') {
        [nextStep] = await tx
          .select()
          .from(workflowSteps)
          .where(eq(workflowSteps.urutan, currentStep.urutan + 1));
      } else if (action === 'REJECT') {
        // Kembali ke draft atau end
        [nextStep] = await tx
          .select()
          .from(workflowSteps)
          .where(eq(workflowSteps.kodeStatus, 'DRAFT'));
      }

      if (!nextStep) throw new Error('Step selanjutnya tidak ditemukan');

      // 4. Catat ke History
      await tx.insert(workflowHistories).values({
        instanceId,
        fromStepId: currentStep.id,
        toStepId: nextStep.id,
        actorId: user.id,
        action,
        catatan,
        createdBy: user.id,
      });

      // 5. Update Instance
      await tx
        .update(workflowInstances)
        .set({
          currentStepId: nextStep.id,
          updatedAt: new Date(),
          updatedBy: user.id,
        })
        .where(eq(workflowInstances.id, instanceId));

      // 6. Sinkronisasi status di Entity (Surat Keluar)
      if (instance.entityType === 'SURAT_KELUAR') {
        await tx
          .update(outgoingLetters)
          .set({ status: nextStep.kodeStatus })
          .where(eq(outgoingLetters.id, instance.entityId));
      }

      await logActivity({
        userId: user.id,
        action: 'UPDATE',
        entityType: 'workflow_instances',
        entityId: instanceId,
        details: { deskripsi: `Workflow Action: ${action}` }
      });
      return nextStep;
    });

    revalidatePath('/surat-keluar');
    return { success: true, data: result };
  } catch (error: any) {
    return { error: 'Gagal memproses workflow', message: error.message };
  }
}

'use server';

import { db } from '@/db';
import { dashboardWidgets, userDashboard, userPreferences, notifications } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';

// ==========================================
// User Preferences
// ==========================================
export async function getUserPreferences(userId: string) {
  try {
    const data = await db.query.userPreferences.findFirst({
      where: eq(userPreferences.userId, userId),
    });
    return { success: true, data };
  } catch (error) {
    return { success: false, error: 'Gagal memuat preferensi' };
  }
}

export async function saveUserPreferences(userId: string, data: any) {
  try {
    const existing = await db.query.userPreferences.findFirst({
      where: eq(userPreferences.userId, userId),
    });

    if (existing) {
      await db.update(userPreferences)
        .set({ ...data, updatedAt: new Date() })
        .where(eq(userPreferences.id, existing.id));
    } else {
      await db.insert(userPreferences).values({ userId, ...data });
    }
    revalidatePath('/dashboard');
    return { success: true };
  } catch (error) {
    return { success: false, error: 'Gagal menyimpan preferensi' };
  }
}

// ==========================================
// Dashboard Widgets
// ==========================================
export async function getAvailableWidgets() {
  try {
    const data = await db.query.dashboardWidgets.findMany({
      where: eq(dashboardWidgets.isAktif, true),
    });
    return { success: true, data };
  } catch (error) {
    return { success: false, error: 'Gagal memuat widget' };
  }
}

export async function getUserDashboard(userId: string) {
  try {
    const data = await db.query.userDashboard.findMany({
      where: and(
        eq(userDashboard.userId, userId),
        eq(userDashboard.isHidden, false)
      ),
      with: {
        widget: true
      },
      orderBy: (ud, { asc }) => [asc(ud.posisi)],
    });
    return { success: true, data };
  } catch (error) {
    return { success: false, error: 'Gagal memuat dashboard' };
  }
}

