'use server';

import { db } from '@/db';
import { menus, permissions } from '@/db/schema';
import { eq, isNull, and, asc } from 'drizzle-orm';
import { getUserPermissions } from '@/lib/auth/rbac';
import { auth } from '@/lib/auth';

/**
 * Mengambil menu dari database yang sesuai dengan hak akses (permission) user saat ini.
 */
export async function getAuthorizedMenus() {
  const session = await auth();
  if (!session?.user?.id) return [];

  const userPerms = await getUserPermissions(session.user.id);

  // Ambil semua menu yang aktif
  const allMenus = await db
    .select({
      id: menus.id,
      nama: menus.nama,
      icon: menus.icon,
      route: menus.route,
      parentId: menus.parentId,
      permissionName: permissions.nama,
    })
    .from(menus)
    .leftJoin(permissions, eq(menus.permissionId, permissions.id))
    .where(eq(menus.isAktif, true))
    .orderBy(asc(menus.urutan));

  // Filter berdasarkan permission
  const authorizedMenus = allMenus.filter((menu) => {
    // Jika tidak butuh permission, semua boleh akses
    if (!menu.permissionName) return true;
    // Jika butuh, cek apakah user punya
    return userPerms.includes(menu.permissionName);
  });

  // Susun menjadi hirarki (Tree)
  const menuMap = new Map();
  const rootMenus: any[] = [];

  // Inisialisasi map
  authorizedMenus.forEach((menu) => {
    menuMap.set(menu.id, { ...menu, children: [] });
  });

  // Build tree
  authorizedMenus.forEach((menu) => {
    if (menu.parentId) {
      const parent = menuMap.get(menu.parentId);
      if (parent) {
        parent.children.push(menuMap.get(menu.id));
      }
    } else {
      rootMenus.push(menuMap.get(menu.id));
    }
  });

  return rootMenus;
}

import { db } from '@/db';
import { eq, and } from 'drizzle-orm';
import { auth } from './index';
import { userRoles, rolePermissions, permissions } from '@/db/schema';

/**
 * Mengambil semua permission yang dimiliki seorang user berdasarkan Role-nya.
 */
export async function getUserPermissions(userId: string): Promise<string[]> {
  // Query untuk mendapatkan semua permission dari role yang dimiliki user
  const userPerms = await db
    .select({
      permissionName: permissions.nama,
    })
    .from(userRoles)
    .innerJoin(rolePermissions, eq(userRoles.roleId, rolePermissions.roleId))
    .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id))
    .where(eq(userRoles.userId, userId));

  // Menggunakan Set untuk menghilangkan duplikat jika user memiliki >1 role dengan permission yang sama
  const permissionSet = new Set(userPerms.map((p) => p.permissionName));
  return Array.from(permissionSet);
}

/**
 * Mengecek apakah user saat ini memiliki permission tertentu.
 * Bisa digunakan di Server Components.
 */
export async function hasPermission(permission: string): Promise<boolean> {
  const session = await auth();
  if (!session?.user?.id) return false;

  const userPerms = await getUserPermissions(session.user.id);
  return userPerms.includes(permission);
}

/**
 * Server Action Guard: Wajibkan permission tertentu.
 * Akan melempar error jika user tidak memiliki permission (atau belum login).
 */
export async function requirePermission(permission: string) {
  const session = await auth();
  if (!session?.user?.id) {
    throw new Error('Unauthorized: Anda harus login untuk mengakses fitur ini.');
  }

  const isAllowed = await hasPermission(permission);
  if (!isAllowed) {
    throw new Error(`Forbidden: Anda tidak memiliki akses (${permission}).`);
  }
}

import { auth } from '@/lib/auth';
import { db } from '@/db';
import { activityLogs } from '@/db/schema';

/**
 * Utilitas untuk mendapatkan User Session aktif.
 * Melempar error jika tidak terautentikasi.
 */
export async function requireAuth() {
  const session = await auth();

  if (!session || !session.user || !session.user.id) {
    throw new Error('Unauthorized: Anda harus login untuk melakukan aksi ini.');
  }

  return { ...session.user, id: session.user.id };
}

/**
 * Utilitas untuk mencatat log aktivitas sistem secara otomatis.
 */
export async function logActivity(params: {
  userId: string;
  action: string;
  entityType: string;
  entityId?: string;
  details?: Record<string, any>;
}) {
  try {
    await db.insert(activityLogs).values({
      userId: params.userId,
      aksi: params.action,
      modul: params.entityType,
      detailAktivitas: `Entity ID: ${params.entityId || 'N/A'}. Details: ${JSON.stringify(params.details || {})}`,
      ipAddress: 'Unknown', // Di masa depan bisa diambil dari request headers middleware
      metadata: params.details,
    });
  } catch (error) {
    console.error('Failed to write activity log:', error);
  }
}
